mapper.update:
UPDATE ISSUE_COMMENT
SET CONTENT = #{content, jdbcType=CLOB},
    UPDATED_AT = SYSTIMESTAMP
WHERE COMMENT_ID = #{commentId}
  AND ISSUE_ID = #{issueId}
  AND MEMBER_ID = #{memberId}
  AND DELETED_AT IS NULL

UPDATE ISSUE_COMMENT
SET DELETED_AT = SYSTIMESTAMP,
    DELETED_BY = #{loginMemberId},
    UPDATED_AT = SYSTIMESTAMP
WHERE COMMENT_ID = #{commentId}
  AND ISSUE_ID = #{issueId}
  AND DELETED_AT IS NULL
  AND EXISTS (
      SELECT 1
      FROM ISSUE I
      INNER JOIN PROJECT P ON P.PROJECT_ID = I.PROJECT_ID
      INNER JOIN PROJECT_MEMBER PM ON PM.PROJECT_ID = P.PROJECT_ID
      WHERE I.ISSUE_ID = ISSUE_COMMENT.ISSUE_ID
        AND I.PROJECT_ID = #{projectId}
        AND I.DELETED_AT IS NULL
        AND P.DELETED_AT IS NULL
        AND PM.MEMBER_ID = #{loginMemberId}
        AND (
            ISSUE_COMMENT.MEMBER_ID = #{loginMemberId}
            OR PM.ROLE = 'ADMIN'
        )
  )
